# cc-code.pl — checks the JavaScript bundled in a Claude Code executable
# against the facts csm relies on, and writes a snapshot of the code
# around each of them for comparison between versions.
#
# Usage: cc-code.pl [-q] [-o DIR] EXECUTABLE
#   -o DIR  write the snapshot to DIR (one file per anchor)
#   -q      print only failed checks and the summary
#
# Minified names change between builds, so checks are written as code
# with "@" standing for any identifier, and snapshots replace short
# identifiers with numbered placeholders. A diff of two snapshots then
# shows changes of logic, not of names.
#
# Exit status: 0 all checks passed, 1 some failed, 2 usage error.

use strict;
use warnings;
use File::Path qw(make_path);
use Getopt::Std;

my %OPT;
getopts('qo:', \%OPT) && @ARGV == 1
	or die "usage: cc-code.pl [-q] [-o DIR] EXECUTABLE\n";
my $FILE = $ARGV[0];

open my $FH, '<:raw', $FILE or die "cc-code.pl: $FILE: $!\n";
my $DATA = do { local $/; <$FH> };
close $FH;

my ($VERSION) = $DATA =~ /VERSION:"(\d+\.\d+\.\d+[\w.+-]*)"/;
$VERSION //= 'unknown';

# Code pattern: everything literal except "@", which is any identifier.
sub pat {
	my ($code) = @_;
	my $re = join '[\w$]+', map { quotemeta } split /\@/, $code, -1;
	return qr/$re/;
}

# Exact text.
sub lit {
	my ($text) = @_;
	return qr/\Q$text\E/;
}

# Bun keeps the source next to compiled bytecode; only text copies count.
sub is_text {
	my ($pos, $len) = @_;
	my $s = $pos > 64 ? $pos - 64 : 0;
	my $chunk = substr($DATA, $s, $len + 128);
	return $chunk !~ /[\x00-\x08\x0e-\x1f]/;
}

# Positions of text matches of a regex.
sub find_all {
	my ($re) = @_;
	my @pos;
	while ($DATA =~ /$re/g) {
		push @pos, [$-[0], $+[0] - $-[0], [map { substr($DATA, $-[$_], $+[$_] - $-[$_]) } 1 .. $#-]]
		    if is_text($-[0], $+[0] - $-[0]);
	}
	return @pos;
}

# Value of a "NAME=number" constant nearest before POS (bundled modules
# have their own scopes, so the nearest definition is the one in use).
sub const_before {
	my ($name, $pos) = @_;
	my $from = $pos > 400000 ? $pos - 400000 : 0;
	my $win = substr($DATA, $from, $pos - $from);
	my $val;
	$val = $1 while $win =~ /(?<![\w\$.])\Q$name\E=(\d+)[,;]/g;
	return $val;
}

# Checks. Each one names the point of prompt.md it confirms and returns
# (ok, detail).
my @CHECKS = (
	['name.encode', '3.2', sub {
		my @m = find_all(pat('function @(@){return @.replace(/[^a-zA-Z0-9]/g,"-")}'));
		return (@m > 0, scalar(@m) . ' match(es)');
	}],
	['name.long', '3.2', sub {
		my @m = find_all(qr/function [\w\$]+\([\w\$]+\)\{let [\w\$]+=([\w\$]+)\([\w\$]+\);if\([\w\$]+\.length<=([\w\$]+)\)return [\w\$]+;return`\$\{[\w\$]+\.slice\(0,\2\)\}-\$\{([\w\$]+)\([\w\$]+\)\}`\}/);
		return (0, 'truncation not found') unless @m;
		my @bad;
		for my $m (@m) {
			my $lim = const_before($m->[2][1], $m->[0]);
			push @bad, "limit $m->[2][1]=" . ($lim // '?') unless defined $lim && $lim == 200;
			my $suffix = substr($DATA, $m->[0] > 3000 ? $m->[0] - 3000 : 0, 6000);
			push @bad, "suffix $m->[2][2] not abs(hash).toString(36)"
			    unless $suffix =~ /function \Q$m->[2][2]\E\([\w\$]+\)\{return Math\.abs\([\w\$]+\([\w\$]+\)\)\.toString\(36\)\}/;
		}
		return (!@bad, @bad ? join('; ', @bad) : 'limit 200, abs(hash) base 36');
	}],
	['name.hash', '3.2', sub {
		my @m = find_all(pat('function @(@){let @=0;for(let @=0;@<@.length;@++)@=(@<<5)-@+@.charCodeAt(@)|0;return @}'));
		return (@m > 0, scalar(@m) . ' match(es)');
	}],
	['read.head-tail', '3.2', sub {
		my @m = find_all(qr/let [\w\$]+=Buffer\.allocUnsafe\(([\w\$]+)\),[\w\$]+=await [\w\$]+\.read\([\w\$]+,0,\1,0\);if\([\w\$]+\.bytesRead===0\)return null;let [\w\$]+=[\w\$]+\.toString\("utf8",0,[\w\$]+\.bytesRead\),[\w\$]+=Math\.max\(0,[\w\$]+\.size-\1\)/);
		return (0, 'head/tail reader not found') unless @m;
		my %sizes;
		$sizes{const_before($_->[2][0], $_->[0]) // '?'}++ for @m;
		my @s = sort keys %sizes;
		return (@s == 1 && $s[0] eq '65536', 'chunk size ' . join(', ', @s));
	}],
	['project.path', '3.2', sub {
		my @m = find_all(pat('@(@.tail,"relocated","relocatedCwd")??@(@.head,"cwd")'));
		return (@m > 0, scalar(@m) . ' match(es): last relocatedCwd in tail, else first cwd in head');
	}],
	['read.last-field', '3.2', sub {
		my @m = find_all(pat('function @(@,@,@){let @=@===void 0?void 0:`"type":"${@}"`,@=`"${@}":`,@=@.length;while(@>0){let @=@.lastIndexOf(`'
		    . "\n" . '`,@-1)'));
		# Since 2.1.325 the scanner takes a fourth argument for lines it
		# cannot parse; lines that parse are read the same way.
		push @m, find_all(pat('function @(@,@,@,@){let @=@===void 0?void 0:@===void 0?[`"type":"${@}"`]:[`"type":"${@}"`,`"type": "${@}"`],@=`"${@}":`,@=@.length;while(@>0){let @=@.lastIndexOf(`'
		    . "\n" . '`,@-1)'));
		return (@m > 0, scalar(@m) . ' match(es): scans tail lines backwards');
	}],
	['read.first-field', '3.2', sub {
		my @m = find_all(pat('function @(@,@){let @=`"${@}":`,@=0;while(@<@.length){let @=@.indexOf(`'
		    . "\n" . '`,@)'));
		return (@m > 0, scalar(@m) . ' match(es): scans head lines forwards');
	}],
	['relocated.record', '3.2', sub {
		my @m = find_all(pat('{type:"relocated",sessionId:@,relocatedCwd:@'));
		my @n = find_all(pat('{type:"relocated",relocatedCwd:this.currentSessionRelocatedCwd,sessionId:@}'));
		return (@m > 0 && @n > 0, scalar(@m) . ' stamp(s), ' . scalar(@n) . ' metadata re-append(s)');
	}],
	['relocated.superseded', '3.2', sub {
		my @m = find_all(pat('`${@}.superseded-${Date.now()}`'));
		return (@m > 0, scalar(@m) . ' match(es)');
	}],
	['title.records', '3.2', sub {
		my @miss;
		for my $c ('{type:"custom-title",customTitle:@,sessionId:@}',
		    '{type:"agent-name",agentName:@,sessionId:@}',
		    '{type:"ai-title",aiTitle:@,sessionId:@}',
		    '{type:"last-prompt",') {
			push @miss, $c unless find_all(pat($c));
		}
		return (!@miss, @miss ? 'missing ' . join(' ', @miss) : 'custom-title, agent-name, ai-title, last-prompt');
	}],
	['title.read', '4.7', sub {
		my @m = find_all(pat('=@(@,"customTitle"),@=@??@(@,"customTitle"),@=@(@,"aiTitle")??@(@,"aiTitle")'));
		# Since 2.1.325 titles are read by record type, not by field name.
		push @m, find_all(pat('=@(@,"custom-title"),@=@??@(@,"custom-title"),@=@(@,"ai-title")??@(@,"ai-title")'));
		return (@m > 0, scalar(@m) . ' match(es): customTitle before aiTitle');
	}],
	['prompt.skip', '3.2', sub {
		my @m = find_all(lit('/^(?:\s*<[a-z][\w-]*[\s>]|\[Request interrupted by user[^\]]*\])/'));
		return (@m > 0, scalar(@m) . ' match(es)');
	}],
	['prompt.first', '4.7', sub {
		my @m = find_all(pat('if(@.type!=="user")return;if(@.isMeta===!0||@.isCompactSummary===!0)return;'));
		return (@m > 0, scalar(@m) . ' match(es): user line, not isMeta, not isCompactSummary');
	}],
	['prompt.command', '4.7', sub {
		my @m = find_all(lit('/<command-name>(.*?)<\/command-name>/'));
		return (@m > 0, scalar(@m) . ' match(es)');
	}],
	['line.fields', '3.2', sub {
		my @m = find_all(pat('version:@(@),gitBranch:@'));
		return (@m > 0, scalar(@m) . ' match(es): version and gitBranch on message lines');
	}],
	['github.add', '3.2', sub {
		my @m = find_all(pat('@=[@,...@];await @((@)=>({...@,githubRepoPaths:{...@.githubRepoPaths,[@]:@}})'));
		my @l = find_all(pat('@=@.toLowerCase(),@=@().githubRepoPaths?.[@]??[]'));
		return (@m > 0 && @l > 0, scalar(@m) . ' prepend(s), ' . scalar(@l) . ' lower-case key lookup(s)');
	}],
	['config.file', '3', sub {
		my @m = find_all(pat('globalConfig:@(@||@(),".claude.json")'));
		return (@m > 0, scalar(@m) . ' match(es): $CLAUDE_CONFIG_DIR/.claude.json, else ~/.claude.json');
	}],
	['sessions-index', '3.2', sub {
		my @m = find_all(qr/sessions-index/);
		return (@m == 0, scalar(@m) . ' mention(s); csm assumes none');
	}],
);

# Snapshot anchors: the function around each match is saved.
my @ANCHORS = (
	['name-encode', qr/\Q.replace(\/[^a-zA-Z0-9]\/g,"-")\E/],
	['name-hash', qr/\(([\w\$]+)<<5\)-\1\+[\w\$]+\.charCodeAt/],
	['read-head-tail', qr/return\{mtime:[\w\$]+\.mtime\.getTime\(\),size:/],
	['read-field', qr/`"\$\{[\w\$]+\}":`/],
	['relocated', qr/"relocated"|relocatedCwd/],
	['superseded', qr/\.superseded-/],
	['titles', qr/"custom-title"|"ai-title"|"agent-name"|customTitle|aiTitle/],
	['last-prompt', qr/"last-prompt"/],
	['prompt', qr/Request interrupted by user\[|<command-name>\(/],
	['message-line', qr/version:[\w\$]+\([\w\$]+\),gitBranch:/],
	['github', qr/githubRepoPaths/],
	['config', qr/globalConfig:[\w\$]+\(/],
	['process-title', qr/process\.title=/],
);

my %KEYWORDS = map { $_ => 1 } qw(
	async await break case catch class const continue default delete do
	else export extends false finally for from function if import in
	instanceof let new null of return static super switch this throw true
	try typeof undefined var void while with yield
	Array Buffer Bun Date Error JSON Map Math Number Object Promise RegExp
	Set String Symbol console process require
);

# Ends of a string literal or template starting at I (opening quote).
sub skip_string {
	my ($s, $i) = @_;
	my $q = substr($s, $i, 1);
	my $n = length $s;
	for ($i++; $i < $n; $i++) {
		my $c = substr($s, $i, 1);
		if ($c eq '\\') {
			$i++;
		} elsif ($c eq $q) {
			return $i + 1;
		}
	}
	return $n;
}

# A "/" after this text starts a regular expression, not a division.
sub regex_may_follow {
	my ($prev) = @_;
	return $prev =~ /(?:^|[(,=:\[!&|?{};+\-*%<>~^])\s*$/
	    || $prev =~ /\b(?:return|typeof|case|in|of|delete|void|throw|new|else|do|instanceof)\s*$/;
}

# End of the regular expression literal starting at I.
sub regex_end {
	my ($s, $i) = @_;
	my $n = length $s;
	my $class = 0;
	for ($i++; $i < $n; $i++) {
		my $c = substr($s, $i, 1);
		return $i if $c eq "\n";
		if ($c eq '\\') {
			$i++;
		} elsif ($c eq '[') {
			$class = 1;
		} elsif ($c eq ']') {
			$class = 0;
		} elsif ($c eq '/' && !$class) {
			$i++;
			$i++ while $i < $n && substr($s, $i, 1) =~ /[a-z]/;
			return $i;
		}
	}
	return $n;
}

# End of the template literal starting at I.
sub template_end {
	my ($s, $i) = @_;
	my $n = length $s;
	for ($i++; $i < $n; $i++) {
		my $c = substr($s, $i, 1);
		if ($c eq '\\') {
			$i++;
		} elsif ($c eq '`') {
			return $i + 1;
		} elsif ($c eq '$' && substr($s, $i + 1, 1) eq '{') {
			$i = code_end($s, $i + 2) - 1;
		}
	}
	return $n;
}

# End of a string, template or regular expression at I, or undef.
sub literal_end {
	my ($s, $i, $prev) = @_;
	my $c = substr($s, $i, 1);
	return skip_string($s, $i) if $c eq '"' || $c eq "'";
	return template_end($s, $i) if $c eq '`';
	return regex_end($s, $i)
	    if $c eq '/' && substr($s, $i + 1, 1) !~ m{[/*]} && regex_may_follow($prev);
	return undef;
}

# Index just past the "}" closing the code that starts at I.
sub code_end {
	my ($s, $i) = @_;
	my $n = length $s;
	my $depth = 0;
	while ($i < $n) {
		my $e = literal_end($s, $i, substr($s, $i > 12 ? $i - 12 : 0, $i > 12 ? 12 : $i));
		if (defined $e) {
			$i = $e;
			next;
		}
		my $c = substr($s, $i, 1);
		$depth++ if $c eq '{';
		if ($c eq '}') {
			return $i + 1 if $depth == 0;
			$depth--;
		}
		$i++;
	}
	return $n;
}

# Innermost "function ...{...}" around POS (with \x01 marking POS), or
# a window of statements around it.
sub enclosing {
	my ($pos, $len) = @_;
	my $from = $pos > 40000 ? $pos - 40000 : 0;
	my $before = substr($DATA, $from, $pos - $from);
	my @starts;
	push @starts, $from + $-[1] while $before =~ /(?:^|[;{}(),=:!&|?])(?:async )?(function)\b/g;
	for my $st (reverse @starts) {
		my $open = index($DATA, '{', $st);
		next if $open < 0 || $open > $pos;
		my $body = substr($DATA, $open + 1, 200000);
		my $end = $open + 1 + code_end($body, 0);
		next unless $end > $pos + $len;
		my $code = substr($DATA, $st, $end - $st);
		substr($code, $pos - $st, 0) = "\x01";
		return $code;
	}
	# Top-level code: the declaration around POS, so the window does not
	# start inside a string.
	my $a = $pos > 2000 ? $pos - 2000 : 0;
	my $head = substr($DATA, $a, $pos - $a);
	my $st = $a;
	$st = $a + $-[0] + 1 while $head =~ /[;}](?:var|let|const) /g;
	my $tail = substr($DATA, $pos + $len, 2000);
	my $end = $tail =~ /[;}](?:var|let|const|function) / ? $pos + $len + $-[0] + 1 : $pos + $len + length $tail;
	my $win = substr($DATA, $st, $end - $st);
	substr($win, $pos - $st, 0) = "\x01";
	return $win;
}

# Short identifiers become numbered placeholders, statements one a line.
sub normalize_into {
	my ($code, $id) = @_;
	my $out = '';
	my $n = length $code;
	my $i = 0;
	while ($i < $n) {
		my $c = substr($code, $i, 1);
		if ($c eq '`') {
			# Template: text as is, expressions normalized.
			my $e = template_end($code, $i);
			my $t = substr($code, $i, $e - $i);
			my $j = 0;
			while ($j < length $t) {
				my $k = index($t, '${', $j);
				$k = length $t if $k < 0;
				while ($k < length $t && substr($t, 0, $k) =~ /\\$/) {
					$k = index($t, '${', $k + 1);
					$k = length $t if $k < 0;
				}
				$out .= substr($t, $j, $k - $j);
				last if $k >= length $t;
				my $x = code_end($t, $k + 2);
				$out .= '${' . normalize_into(substr($t, $k + 2, $x - $k - 3), $id) . '}';
				$j = $x;
			}
			$i = $e;
			next;
		}
		my $e = literal_end($code, $i, substr($out, -12));
		if (defined $e) {
			$out .= substr($code, $i, $e - $i);
			$i = $e;
		} elsif (substr($code, $i, 64) =~ /^([A-Za-z_\$][\w\$]*)/) {
			my $w = $1;
			my $rest = substr($code, $i + length $w, 1);
			my $keep = $KEYWORDS{$w} || length($w) > 5
			    || $out =~ /(?<!\.\.)\.$/
			    || ($rest eq ':' && $out =~ /[{,]\n?$/);
			$out .= $keep ? $w : ($id->{$w} //= '§' . (keys(%$id) + 1));
			$i += length $w;
		} else {
			$out .= $c;
			$out .= "\n" if $c eq ';' || $c eq '{' || $c eq '}';
			$i++;
		}
	}
	return $out;
}

# Normalized snippet; a long function is cut to the lines around \x01.
sub normalize {
	my ($code) = @_;
	my $out = normalize_into($code, {});
	$out =~ s/chunk-[a-z0-9]{8}\.js/chunk-§.js/g;
	my @lines = split /\n/, $out;
	if (@lines > 60) {
		my ($at) = grep { $lines[$_] =~ /\x01/ } 0 .. $#lines;
		$at //= 0;
		my $a = $at > 25 ? $at - 25 : 0;
		my $b = $at + 25 < $#lines ? $at + 25 : $#lines;
		@lines = ($a > 0 ? ('…') : (), @lines[$a .. $b], $b < $#lines ? ('…') : ());
	}
	$out = join "\n", @lines;
	$out =~ s/\x01//g;
	$out =~ s/[\x00-\x08\x0b-\x1f\x7f]/?/g;
	return $out;
}

my $FAILED = 0;
print "Claude Code $VERSION ($FILE)\n" unless $OPT{q};
for my $c (@CHECKS) {
	my ($name, $ref, $fn) = @$c;
	my ($ok, $detail) = $fn->();
	$FAILED++ unless $ok;
	printf "%-4s %-22s %-5s %s\n", $ok ? 'ok' : 'FAIL', $name, $ref, $detail
	    if !$ok || !$OPT{q};
}
printf "cc-code: %d checks, %d failed\n", scalar @CHECKS, $FAILED;

if ($OPT{o}) {
	my $DIR = $OPT{o};
	-d $DIR or make_path($DIR) or die "cc-code.pl: $DIR: $!\n";
	for my $a (@ANCHORS) {
		my ($name, $re) = @$a;
		my %seen;
		$seen{normalize(enclosing($_->[0], $_->[1]))} = 1 for find_all($re);
		open my $out, '>', "$DIR/$name.js" or die "cc-code.pl: $DIR/$name.js: $!\n";
		print $out "// $name: ", scalar(keys %seen), " unique snippet(s)\n";
		print $out "\n$_\n" for sort keys %seen;
		close $out;
	}
	print "snapshot: $DIR\n" unless $OPT{q};
}
exit($FAILED ? 1 : 0);
